const results = [];

for (let i = 0; i < $input.all().length; i++) {
  const geminiItem = $input.all()[i];
  const prepItem   = $('Prepare Email Data').all()[i];
  const config     = prepItem?.json?.config || {};

  // Parse Gemini JSON response
  let extracted = {};
  try {
    const text = geminiItem.json?.candidates?.[0]?.content?.parts?.[0]?.text;
    extracted = JSON.parse(text);
  } catch (e) {
    extracted = geminiItem.json || {};
  }

  const cwRaw    = extracted.chargeableWeightKg || 0;
  const billableCW = Math.max(config.minChargeableWeight || 45, cwRaw);
  const sellingAirFreight = (extracted.airFreightRatePerKg || 0) + (config.markupAirFreightPerKg || 0.50);
  const fuelRate   = Math.max(extracted.fuelRatePerKg   || 0, config.fuelRatePerKg   || 0.10);
  const secRate    = Math.max(extracted.secRatePerKg    || 0, config.secRatePerKg    || 0.05);
  const screenRate = Math.max(extracted.screenRatePerKg || 0, config.screenRatePerKg || 0.10);

  results.push({
    json: {
      token:             'REPLACE_WITH_YOUR_SECRET_TOKEN',
      pod:               extracted.pod         || '',
      airlineCode:       extracted.airlineCode || '',
      transitTime:       extracted.transitTime || '',
      sellingAirFreight: sellingAirFreight,
      billableCW:        billableCW,
      fuelRate:          fuelRate,
      fuelUnit:          'PER KG',
      secRate:           secRate,
      secUnit:           'PER KG',
      screenRate:        screenRate,
      screenUnit:        'PER KG',
      emailId:           prepItem?.json?.emailId || ''
    }
  });
}

return results;

for (const item of $input.all()) {
  const res = item.json;
  if (res.status !== 'ok') {
    throw new Error('Apps Script error: ' + (res.message || JSON.stringify(res)));
  }
  console.log('Quotation written at row:', res.startRow);
}
